import re,glob
txt={}
for f in glob.glob('blueprint/src/chapters/*.tex')+glob.glob('blueprint/src/*.tex'):
    txt[f]=open(f).read()
all_labels=set()
for f,s in txt.items():
    all_labels|=set(re.findall(r'\\label\{([^}]*)\}',s))
missing={}
for f,s in txt.items():
    for m in re.findall(r'\\(?:cref|Cref|ref|uses)\{([^}]*)\}',s):
        for lab in [x.strip() for x in m.split(',')]:
            if lab and lab not in all_labels:
                missing.setdefault(lab,set()).add(f)
print("dangling refs:", len(missing))
for k,v in sorted(missing.items())[:20]: print("  ",k,"<-",sorted(v))
# lean decls referenced
leans=set()
for f,s in txt.items():
    leans|=set(re.findall(r'\\lean\{([^}]*)\}',s))
print("total \\lean decls:",len(leans))
print("references deleted decl:", [l for l in leans if 'hasRationalPoint_of_curve'==l.split('.')[-1]])
